using System;using System.Collections.Generic;using RimWorld;using UnityEngine;using Verse;
namespace ElementalHearts {
 public static class CelestialCombat {
  [ThreadStatic]public static int counterDepth;
  public static bool Hostile(Pawn p,Pawn target){return p!=null&&target!=null&&target!=p&&p.Spawned&&target.Spawned&&target.Map==p.Map&&!target.Dead&&!target.Downed&&!target.IsPrisoner&&target.HostileTo(p);}
  public static bool Eligible(Pawn p,Pawn target){return p!=null&&target!=null&&target!=p&&p.Spawned&&target.Spawned&&target.Map==p.Map&&!target.Dead&&!target.Downed&&ElementalCombatPolicy.TargetAllowed(ElementalManualTarget.Explicit(p,target),ElementalHeartsMod.Settings.friendlyFire,target.IsPrisoner,target.HostileTo(p));}
  public static List<Pawn> Targets(Pawn p,IntVec3 center,float radius,int limit){var result=new List<Pawn>();if(p==null||!p.Spawned)return result;int scanned=0;var seen=new HashSet<int>();foreach(var cell in GenRadial.RadialCellsAround(center,Math.Min(14,radius),true)){if(!cell.InBounds(p.Map)||ElementalCombatPolicy.Controlled(p)&&cell.Fogged(p.Map)||!LightningCombat.ClearLine(center,cell,p.Map))continue;var things=cell.GetThingList(p.Map);for(int i=0;i<things.Count;i++){if(++scanned>CelestialRules.MaxSearchThings)return result;var target=things[i] as Pawn;if(!Eligible(p,target)||!seen.Add(target.thingIDNumber))continue;result.Add(target);if(result.Count>=Math.Min(CelestialRules.MaxCandidates,limit))return result;}}return result;}
  public static Pawn Nearest(Pawn p,float range){Pawn best=null;int distance=int.MaxValue;foreach(var target in Targets(p,p.Position,range,CelestialRules.MaxCandidates)){if(!Hostile(p,target))continue;int d=p.Position.DistanceToSquared(target.Position);if(d<distance||d==distance&&best!=null&&target.thingIDNumber<best.thingIDNumber){best=target;distance=d;}}return best;}
  public static int Crowd(Pawn p){int n=0;foreach(var target in Targets(p,p.Position,4.5f,CelestialRules.MaxCandidates))if(Hostile(p,target)&&++n>=2)break;return n;}
  public static bool Free(Pawn p,IntVec3 cell){if(p==null||!p.Spawned||!cell.InBounds(p.Map)||!cell.Standable(p.Map)||ElementalCombatPolicy.Controlled(p)&&cell.Fogged(p.Map))return false;foreach(var thing in cell.GetThingList(p.Map))if(thing is Pawn&&thing!=p||thing is Fire)return false;return true;}
  public static bool Path(Pawn p,IntVec3 from,IntVec3 to){IntVec3 prior=from;foreach(var cell in LightningGeometry.Trace(from,to)){if(!Free(p,cell)||!LightningCombat.Open(cell,p.Map))return false;int dx=cell.x-prior.x,dz=cell.z-prior.z;if(dx!=0&&dz!=0&&(!Free(p,new IntVec3(prior.x+dx,0,prior.z))||!Free(p,new IntVec3(prior.x,0,prior.z+dz))))return false;prior=cell;}return true;}
  public static bool Landing(Pawn p,IntVec3 from,Pawn target,float range,out IntVec3 landing){landing=IntVec3.Invalid;if(target==null||!target.Spawned||target.Map!=p.Map)return false;int best=int.MaxValue;for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++){if(x==0&&z==0)continue;var cell=target.Position+new IntVec3(x,0,z);int d=from.DistanceToSquared(cell);if(d==0||d>range*range||d>=best||!Free(p,cell)||!Path(p,from,cell)||!LightningCombat.ClearLine(cell,target.Position,p.Map))continue;landing=cell;best=d;}return landing.IsValid;}
  public static bool Retreat(Pawn p,Pawn target,out IntVec3 retreat){retreat=IntVec3.Invalid;var threats=Targets(p,p.Position,10,CelestialRules.MaxCandidates);if(!threats.Contains(target))threats.Add(target);int before=int.MaxValue;foreach(var t in threats)if(Hostile(p,t))before=Math.Min(before,p.Position.DistanceToSquared(t.Position));float best=float.MinValue;foreach(var cell in GenRadial.RadialCellsAround(p.Position,4,true)){if(p.Position.DistanceToSquared(cell)<4||!Free(p,cell)||!Path(p,p.Position,cell))continue;int separation=int.MaxValue;foreach(var t in threats)if(Hostile(p,t))separation=Math.Min(separation,cell.DistanceToSquared(t.Position));if(separation<=before||separation<4)continue;float score=separation-.15f*cell.DistanceToSquared(p.Position);if(score>best){best=score;retreat=cell;}}return retreat.IsValid;}
  public static void Push(Pawn caster,Pawn target,int cells){if(!Hostile(caster,target)||ElementalAnimationBridge.ExternallyControlled(target)||CycloneAirbound.Active(target))return;IntVec3 start=target.Position,last=start;int x=Math.Sign(start.x-caster.Position.x),z=Math.Sign(start.z-caster.Position.z);if(x==0&&z==0)x=1;for(int i=1;i<=Math.Min(3,cells);i++){var next=start+new IntVec3(x*i,0,z*i);if(!Free(target,next)||!Path(target,last,next))break;last=next;}if(last!=start)ThunderstormBlitz.Move(target,last);}
  public static bool Strike(Pawn source,Pawn target,float damage,float penetration,ThingDef weapon,float multiplier){
   if(!Eligible(source,target))return false;if(counterDepth==0&&WaterDefense.TryParry(source,target))return false;
   float amount=Math.Max(0,damage*multiplier);if(ElementalNonLethal.TryApply(source,target,amount))return false;
   var result=target.TakeDamage(new DamageInfo(DefDatabase<DamageDef>.GetNamed("EH_SolarDamage"),amount,Math.Max(.9f,penetration),-1,source,null,weapon,DamageInfo.SourceCategory.ThingOrUnknown,target));return result!=null&&result.totalDamageDealt>0;
  }
 }
 public sealed class CelestialRadianceEntry:IExposable {public Pawn source;public int stacks,until;public void ExposeData(){Scribe_References.Look(ref source,"source");Scribe_Values.Look(ref stacks,"stacks");Scribe_Values.Look(ref until,"until");}}
 public sealed class HediffCompProperties_CelestialRadiance:HediffCompProperties {public HediffCompProperties_CelestialRadiance(){compClass=typeof(HediffComp_CelestialRadiance);}}
 public sealed class HediffComp_CelestialRadiance:HediffComp {
  public List<CelestialRadianceEntry> entries=new List<CelestialRadianceEntry>();int nextVisual;
  public override void CompExposeData(){Scribe_Collections.Look(ref entries,"EH_celestialRadianceOwners",LookMode.Deep);if(entries==null)entries=new List<CelestialRadianceEntry>();}
  public int Stacks(Pawn source,int now){foreach(var e in entries)if(e!=null&&e.source==source&&e.until>now)return Math.Max(0,Math.Min(3,e.stacks));return 0;}
  public void Expire(int now){for(int i=entries.Count-1;i>=0;i--)if(entries[i]==null||entries[i].source==null||entries[i].source.Destroyed||entries[i].until<=now)entries.RemoveAt(i);while(entries.Count>8)entries.RemoveAt(0);}
  public void Refresh(){int max=1;foreach(var e in entries)max=Math.Max(max,Math.Min(3,e.stacks));parent.Severity=max;}
  public void Add(Pawn source,int now){Expire(now);foreach(var e in entries)if(e.source==source){e.stacks=Math.Min(3,e.stacks+1);e.until=now+480;Refresh();return;}if(entries.Count>=8){int oldest=0;for(int i=1;i<entries.Count;i++)if(entries[i].until<entries[oldest].until)oldest=i;entries.RemoveAt(oldest);}entries.Add(new CelestialRadianceEntry{source=source,stacks=1,until=now+480});Refresh();}
  public void Consume(Pawn source){entries.RemoveAll(e=>e==null||e.source==source);Refresh();}
  public override void CompPostTickInterval(ref float adjustment,int delta){int now=Find.TickManager.TicksGame;Expire(now);if(entries.Count==0){Pawn.health.RemoveHediff(parent);return;}Refresh();if(Pawn.Spawned&&!Pawn.Dead&&!Pawn.Downed&&now>=nextVisual){nextVisual=now+36;CelestialVfx.Emit(Pawn,CelestialEffect.Radiance,Pawn.DrawPos+new Vector3(0,0,.6f),Pawn.DrawPos,36,.5f,.5f,Pawn);}}
  public override string CompTipStringExtra{get{return "Up to three Radiance marks per Celestial. Each caster owns their marks; Solar Judgment spends only that caster's marks. Eight-second expiry.";}}
 }
 public static class CelestialRadiance {
  public static HediffComp_CelestialRadiance On(Pawn p){if(p==null||p.health==null)return null;foreach(var h in p.health.hediffSet.hediffs)if(h.def.defName=="EH_CelestialRadiance")return h.TryGetComp<HediffComp_CelestialRadiance>();return null;}
  public static int Stacks(Pawn source,Pawn target){var c=On(target);return c==null?0:c.Stacks(source,Find.TickManager.TicksGame);}
  public static void Apply(Pawn source,Pawn target){if(target==null||target.Dead||target.Downed||!target.Spawned)return;var c=On(target);if(c==null)c=target.health.AddHediff(DefDatabase<HediffDef>.GetNamed("EH_CelestialRadiance")).TryGetComp<HediffComp_CelestialRadiance>();if(c!=null)c.Add(source,Find.TickManager.TicksGame);}
  public static void Consume(Pawn source,Pawn target){var c=On(target);if(c==null)return;c.Consume(source);if(c.entries.Count==0)target.health.RemoveHediff(c.parent);}
 }
}
